        <option value="">Person…</option>
        {(people.data ?? []).map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="crew-member-add"
        disabled={add.isPending}
        onClick={() => {
          if (!submit.begin()) return;
          add.reset();
          // nothing chosen: no person 0, so the server refuses it
          add.mutate(Number(chosen));
        }}
      >
        Add member
      </button>
      {add.isError && <span data-testid="crew-error"> Could not add this member.</span>}
    </li>
  );
}

/** The sheet's crews: the form that adds one (its name trimmed, not blank, not already taken, and a lead from the
 *  people), and each crew's row. */
function Crews({ sheetId, user }: { sheetId: string; user: string }) {
  const crews = useCrews(sheetId);
  const people = usePeople(sheetId);
  const due = usePeopleDue(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [lead, setLead] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (c: { name: string; leadId: number | null }) =>
      postJson<Crew>(`/api/sheets/${encodeURIComponent(sheetId)}/crews`, { ...c, by: user }),
    onSuccess: async () => {
      setName('');
      setLead('');
      await queryClient.invalidateQueries({ queryKey: crewsKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <section data-testid="crews">
      <h3>Crews</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          add.reset();
          add.mutate({ name, leadId: lead === '' ? null : Number(lead) });
        }}
      >
        <input
          data-testid="crew-form-name"
          placeholder="Crew name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            add.reset();
          }}
        />{' '}
        <select
          data-testid="crew-form-lead"
          value={lead}
          onChange={(e) => {
            setLead(e.target.value);
            add.reset();
          }}
        >
          <option value="">Lead…</option>
          {(people.data ?? []).map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button type="submit" data-testid="crew-form-submit" disabled={add.isPending}>
          Add crew
        </button>
        {add.isError && <span data-testid="crew-form-error"> A crew's name must not be blank nor already taken, and it needs a lead.</span>}
      </form>
      {crews.isError && <p data-testid="crews-load-error">Could not load crews.</p>}
      <ul>
        {(crews.data ?? []).map((c) => (
          <CrewRow key={c.name} sheetId={sheetId} user={user} crew={c} due={due} />
        ))}
      </ul>
    </section>
  );
}

export const contributions = [SheetPage.fill({ order: 9.75, Component: Crews })];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/people';
import { sum } from '../rates/rates';

/** A member of a crew: the person's `personId` and `name`. */
export type CrewMember = { personId: number; name: string };

/** A crew of the sheet: its `name` (trimmed, unique on the sheet), its lead (`leadId`, `lead` their name; null and blank once the lead has left the sheet) and its
 *  members in the order added (never the lead, a person at most once). A person can be in several crews. */
export type Crew = { name: string; leadId: number | null; lead: string; members: CrewMember[] };

/** Under the people's key, so every change to a person (a rename or merge above all) reloads the crews. */
export const crewsKey = (sheetId: string) => [...peopleKey(sheetId), 'crews'];

/** The sheet's crews, in the order added. */
export function useCrews(sheetId: string) {
  return useQuery({
    queryKey: crewsKey(sheetId),
    queryFn: () => getJson<Crew[]>(`/api/sheets/${encodeURIComponent(sheetId)}/crews`),
  });
}

/** A crew's due-total: its lead's and its members' due-totals (as their rows show them) added up, skipping n/a. */
export function crewDueTotal(crew: Crew, due: Map<number, string>): string {
  return sum([...(crew.leadId === null ? [] : [crew.leadId]), ...crew.members.map((m) => m.personId)].map((id) => due.get(id) ?? 'n/a'));
}
import { useCallback, useEffect, useState } from 'react';
import { useIsFetching, useMutation, useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { ReadNow } from '../../query/readNow';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useClaims } from '../claims/claims';
import { usePeopleDue } from '../header/totals';
import { usePeople } from '../people/people';
import { useRates } from '../rates/rates';
import { useSettings } from '../settings/settings';

/** One sheet's people, in list order, each with their names (name then aliases) and due-total as their row shows it. */
type Found = { sheetId: string; name: string; names: string[]; due: string }[];

/** Works out one sheet's people and due-totals with the same hooks as its rows, and reports them once all are read.
 *  Shows nothing. */
function SheetPeople({ sheetId, report }: { sheetId: string; report: (sheetId: string, found: Found) => void }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId);
  const due = usePeopleDue(sheetId);
  const fetching = useIsFetching({ queryKey: ['sheet', sheetId] });
  const ready = fetching === 0 && people.isSuccess && claims.isSuccess && rates.isSuccess && settings.isSuccess;
  const found: Found | null = ready
    ? people.data.map((p) => ({ sheetId, name: p.name, names: [p.name, ...(p.aliases ?? [])], due: due.get(p.id) ?? 'n/a' }))
    : null;
  const key = found === null ? null : JSON.stringify(found);
  useEffect(() => {
    if (key !== null) report(sheetId, JSON.parse(key) as Found);
  }, [report, sheetId, key]);
  return null;
}

/** The tree search: every person, over this sheet and every other sheet of its tree, whose name or an alias contains the
 *  typed text (case ignored), one line each as `<sheet id> <name> <due-total>`: this sheet's people first in list order,
 *  then the other sheets' by sheet id. The sheets are read as they are now, afresh on each press. */
function TreeSearch({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const [found, setFound] = useState<Record<string, Found>>({});
  const search = useMutation({
    mutationFn: async (typed: string) => {
      const others = await getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/tree`);
      const sheets = [sheetId, ...others];
      // re-read every sheet so what another user changed is seen
      await Promise.all(sheets.map((id) => queryClient.refetchQueries({ queryKey: ['sheet', id] })));
      return { typed: typed.trim().toLowerCase(), sheets };
    },
  });
  const report = useCallback((id: string, f: Found) => setFound((all) => ({ ...all, [id]: f })), []);
  const done = search.data !== undefined && search.data.sheets.every((id) => found[id] !== undefined);
  const lines = done
    ? search.data!.sheets.flatMap((id) =>
        found[id].filter((p) => p.names.some((n) => n.toLowerCase().includes(search.data!.typed))),
      )
    : [];

  return (
    <section data-testid="tree-search">
      <h3>Search the tree</h3>
      <input
        data-testid="search-name"
        placeholder="Name or alias"
        value={text}
        onChange={(e) => {
          setText(e.target.value);
          search.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="search"
        disabled={search.isPending}
        onClick={() => {
          search.reset();
          setFound({});
          search.mutate(text);
        }}
      >
        Search
      </button>
      {search.isError && <p data-testid="search-error">Could not search the tree.</p>}
      {search.data !== undefined && (
        <ReadNow.Provider value={true}>
          {search.data.sheets.map((id) => (
            <SheetPeople key={id} sheetId={id} report={report} />
          ))}
        </ReadNow.Provider>
      )}
      {done && (
        <>
          {' '}
          Found <span data-testid="search-count">{lines.length}</span>
        </>
      )}
      <ul>
        {lines.map((p, i) => (
          <li key={i} data-testid="search-line">
            {p.sheetId} {p.name} {p.due}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 89, Component: TreeSearch });

